// Minimise f(x,y) = 0.5*(x^2 + 100*y^2)
// Gradient = (x, 100y). Lipschitz constant L = 100.
const L = 100, alpha = 1/L;
const N = 80;

function gd(x0, y0){
  let x=x0, y=y0;
  const hist = [];
  for(let k=0;k<N;k++){
    const f = 0.5*(x*x + 100*y*y);
    hist.push(f);
    x = x - alpha*x;
    y = y - alpha*(100*y);
  }
  return hist;
}

function nesterov(x0, y0){
  let x=x0, y=y0, xp=x0, yp=y0;
  const hist = [];
  for(let k=0;k<N;k++){
    const beta = k/(k+3);
    const ux = x + beta*(x-xp), uy = y + beta*(y-yp);
    xp=x; yp=y;
    x = ux - alpha*ux;
    y = uy - alpha*(100*uy);
    hist.push(0.5*(x*x + 100*y*y));
  }
  return hist;
}

const g = gd(1, 1);
const n = nesterov(1, 1);
console.log('iter  GD                NAG');
for(let k of [0,5,10,20,40,79]){
  console.log(k.toString().padStart(4) + '  ' + g[k].toExponential(3) + '   ' + n[k].toExponential(3));
}
console.log('\nAfter 80 iterations:');
console.log('  GD          : ' + g[N-1].toExponential(3));
console.log('  Nesterov NAG: ' + n[N-1].toExponential(3));
console.log('  ratio       : ' + (g[N-1]/n[N-1]).toFixed(1) + 'x');
